class TXS {
  TXS._(this._bc, this._bcOffset);
  factory TXS(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<TXS> reader = _TXSReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

