  ///  set. Never a source's own identifier and never a coordinate string.
  String? get ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  ///  Winning source's native facility identifier, copied verbatim from the
  ///  SOURCES entry named by CONSENSUS.WINNING_PROVIDER_ID. Never a substitute
  ///  for ID and never stable across sources.
  String? get NATIVE_ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 6);
  String? get nativeId => NATIVE_ID;
  ///  Facility or structure name verbatim when a source publishes one. Never
  ///  synthesized from coordinates, licensee, or nearest settlement.
  String? get SITE_NAME => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 8);
  String? get siteName => SITE_NAME;
  ///  Station identification the facility as a whole answers to, verbatim: a
  ///  callsign, an assigned station identifier, or the identifier an observer
  ///  community records. Per-emission identity lives in
  ///  EMISSIONS[].STATION_IDENTITY.
  String? get STATION_IDENTITY => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 10);
  String? get stationIdentity => STATION_IDENTITY;
  ///  Licensee, operator or responsible administration name verbatim as the
  ///  cited source states it. A display name, never an identifier: consumers
  ///  must not treat it as a stable key.
  String? get LICENSEE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 12);
  ///  Licence, assignment or authorization identifier verbatim.
  String? get LICENSE_ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 14);
  String? get licenseId => LICENSE_ID;
  ///  Primary service class of the facility. Individual emissions may state
  ///  their own.
  txsServiceClass get SERVICE => txsServiceClass.fromValue(const fb.Int8Reader().vTableGet(_bc, _bcOffset, 16, 0));
  txsOperationalStatus get STATUS => txsOperationalStatus.fromValue(const fb.Int8Reader().vTableGet(_bc, _bcOffset, 18, 0));
  ///  ISO 3166-1 alpha-2 country code, uppercase, as the source states it.
  String? get COUNTRY_CODE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 20);
  String? get countryCode => COUNTRY_CODE;
  ///  Administrative subdivision or locality verbatim as the source states it.
  String? get ADMIN_AREA => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 22);
  String? get adminArea => ADMIN_AREA;
  ///  Published facility position, decimal degrees on WGS 84, produced by the
  ///  merge described in CONSENSUS. ABSENT when no source publishes a position:
  ///  a region centroid is never substituted. Per-source positions before
  ///  reconciliation live in SOURCES[].REPORTED_LATITUDE/REPORTED_LONGITUDE and
  ///  are never overwritten by this value.
  double get LATITUDE => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 24, 0.0);
  double get LONGITUDE => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 26, 0.0);
  ///  The class of authority behind LATITUDE/LONGITUDE. A consumer that renders
  ///  a position without reading this field is rendering an unlabelled claim.
  txsPositionAuthorityClass get POSITION_AUTHORITY => txsPositionAuthorityClass.fromValue(const fb.Int8Reader().vTableGet(_bc, _bcOffset, 28, 0));
  txsPositionAuthorityClass get positionAuthority => POSITION_AUTHORITY;
  ///  Horizontal envelope in metres within which the facility is asserted to
  ///  lie, as the publisher states it. Zero means unpublished — never that the
  ///  position is exact.
  double get POSITION_UNCERTAINTY_M => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 30, 0.0);
  double get positionUncertaintyM => POSITION_UNCERTAINTY_M;
  ///  Credible consulted sources place the facility in materially different
  ///  locations, or a source states the position is contested. The published
  ///  coordinate remains the publisher's best merge; this flag forbids a
  ///  consumer from presenting it as settled.
  bool get POSITION_DISPUTED => const fb.BoolReader().vTableGet(_bc, _bcOffset, 32, false);
  bool get positionDisputed => POSITION_DISPUTED;
  ///  Positions the facility is asserted to have vacated, most recent first.
  List<TXSPriorPosition>? get PRIOR_POSITIONS => const fb.ListReader<TXSPriorPosition>(TXSPriorPosition.reader).vTableGetNullable(_bc, _bcOffset, 34);
  List<TXSPriorPosition>? get priorPositions => PRIOR_POSITIONS;
  ///  Ground elevation at the facility, metres above mean sea level as the
  ///  source states it. Zero means unpublished.
  double get GROUND_ELEVATION_AMSL_M => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 36, 0.0);
  double get groundElevationAmslM => GROUND_ELEVATION_AMSL_M;
  ///  Overall height of the antenna-supporting structure above ground level,
  ///  metres. Distinct from any emission's antenna height. Zero means
  ///  unpublished.
  double get STRUCTURE_HEIGHT_AGL_M => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 38, 0.0);
  double get structureHeightAglM => STRUCTURE_HEIGHT_AGL_M;
  txsStructureClass get STRUCTURE => txsStructureClass.fromValue(const fb.Int8Reader().vTableGet(_bc, _bcOffset, 40, 0));
  ///  Number of antenna-supporting structures at the facility. Zero means
  ///  unpublished.
  int get STRUCTURE_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 42, 0);
  int get structureCount => STRUCTURE_COUNT;
  ///  Every emission the facility is documented to radiate.
  List<TXSEmission>? get EMISSIONS => const fb.ListReader<TXSEmission>(TXSEmission.reader).vTableGetNullable(_bc, _bcOffset, 44);
  ///  RFC 3339 UTC fixed-millisecond bounds of the documentation or observation
  ///  window backing the published record.
  String? get FIRST_OBSERVED => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 46);
  String? get firstObserved => FIRST_OBSERVED;
  String? get LAST_OBSERVED => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 48);
  String? get lastObserved => LAST_OBSERVED;
  ///  Every source consulted for this facility, including sources that returned
  ///  nothing. Required: a facility with no named sources is not publishable.
  List<TXSProvenance>? get SOURCES => const fb.ListReader<TXSProvenance>(TXSProvenance.reader).vTableGetNullable(_bc, _bcOffset, 50);
