  ///  Required: a published position always states the rule that produced it,
  ///  including SINGLE_SOURCE.
  TXSConsensus? get CONSENSUS => TXSConsensus.reader.vTableGetNullable(_bc, _bcOffset, 52);

  @override
  String toString() {
    return 'TXS{ID: ${ID}, nativeId: ${nativeId}, siteName: ${siteName}, stationIdentity: ${stationIdentity}, LICENSEE: ${LICENSEE}, licenseId: ${licenseId}, SERVICE: ${SERVICE}, STATUS: ${STATUS}, countryCode: ${countryCode}, adminArea: ${adminArea}, LATITUDE: ${LATITUDE}, LONGITUDE: ${LONGITUDE}, positionAuthority: ${positionAuthority}, positionUncertaintyM: ${positionUncertaintyM}, positionDisputed: ${positionDisputed}, priorPositions: ${priorPositions}, groundElevationAmslM: ${groundElevationAmslM}, structureHeightAglM: ${structureHeightAglM}, STRUCTURE: ${STRUCTURE}, structureCount: ${structureCount}, EMISSIONS: ${EMISSIONS}, firstObserved: ${firstObserved}, lastObserved: ${lastObserved}, SOURCES: ${SOURCES}, CONSENSUS: ${CONSENSUS}}';
  }
